    if poses.ndim != 3 or poses.shape[-1] != 3:
        raise ValueError(f"poses must be [B, T, 3], got {poses.shape}")
    wb = float(np.asarray(wheel_base).reshape(-1)[0])
    vehicle = VehicleParameters(wheel_base=wb, width=float(width))

    tracker = BatchLQRTracker(discretization_time=dt, vehicle=vehicle)
    motion_model = BatchKinematicBicycleModel(vehicle=vehicle)
    tracker._discretization_time = dt

