    tracker.update(proposal_states)

    simulated = np.zeros_like(proposal_states)
    simulated[:, 0] = proposal_states[:, 0]  # start ON the plan, as navsim does

    delta = TimeDuration.from_s(dt)
    current = SimulationIteration(TimePoint(0), 0)
    nxt = SimulationIteration(TimePoint(0) + delta, 1)
    for time_idx in range(1, poses.shape[1]):
        sampling_time = nxt.time_point - current.time_point
        command_states = tracker.track_trajectory(current, nxt, simulated[:, time_idx - 1])
        simulated[:, time_idx] = motion_model.propagate_state(
            states=simulated[:, time_idx - 1],
            command_states=command_states,
            sampling_time=sampling_time,
        )
        current = nxt
        nxt = SimulationIteration(current.time_point + delta, 1 + time_idx)
    return simulated
